from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books: set[str] = set()
        # book_id -> (user, borrow_date)
        self.loans: dict[str, tuple[str, date]] = {}
        # user -> list of (book_id, due_date) or simple unpaid amount
        self.fines: dict[str, float] = {}

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Unknown book: {book_id}")
        if book_id in self.loans:
            raise ValueError(f"Book already borrowed: {book_id}")
        # A user with unpaid fines may hold at most one book at a time.
        if self.fines.get(user, 0.0) > 0:
            for b, (u, _) in self.loans.items():
                if u == user:
                    raise ValueError(
                        f"User {user} has unpaid fines and already holds a book"
                    )
        self.loans[book_id] = (user, day)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self.loans:
            raise ValueError(f"Book not borrowed: {book_id}")
        borrower, borrow_day = self.loans[book_id]
        if borrower != user:
            raise ValueError(f"Book {book_id} was not borrowed by {user}")
        del self.loans[book_id]

        due = borrow_day + timedelta(days=self.loan_days)
        if day <= due:
            return 0.0

        # Count only weekdays as delay days.
        delay_days = 0
        d = due + timedelta(days=1)
        while d <= day:
            if d.weekday() < 5:  # Monday..Friday
                delay_days += 1
            d += timedelta(days=1)

        fine = delay_days * self.daily_fine
        if fine > 0:
            self.fines[user] = self.fines.get(user, 0.0) + fine
        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        self.fines.pop(user, None)
